    vec4 lifeTime; // x: 当前生命值, y: 整个生命周期, z: 一直存在, w: color alpha random
    vec4 originPos;// 保留初始位置
};
// 粒子双缓冲SSBO定义
layout(std430, binding=0) buffer InputBufferParticles {
    Particle particlesIn[];
};
layout(std430, binding=1) buffer OutputBufferParticles {
    Particle particlesOut[];
};

uniform float u_Time;
uniform float dt;

// @Range(扰动间隔, 0.5, 5.0, 0.1)=2.0
uniform float noiseInterval;

// @Range(单次扰动持续时间,0.5, 5.0, 0.1)=1.0
uniform float noiseDuration;

// @Vec3(扰动强度,0.01)=[2.0,0.5,2.0]                 // 扰动强度 0.5 ~ 5.0
uniform vec3 turbulenceForce;


// 三维Perlin噪声实现（适用于粒子系统湍流场）
float mod289(float x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 permute(vec4 x) { return mod289(((x * 34.0) + 1.0) * x); }

float perlin_noise(vec3 p) {
    // 网格划分（网页1的晶格优化方法）
    vec3 a = floor(p);
    vec3 d = p - a;
    vec3 u = d * d * d * (d * (d * 6.0 - 15.0) + 10.0); // 五次缓动曲线（网页6的优化）

    // 哈希梯度生成（结合网页1和网页6的算法）
    a = mod289(a);
    vec4 p_x = permute(a.x + vec4(0.0, 1.0, 0.0, 1.0));
    vec4 p_y = permute(a.y + p_x + vec4(0.0, 0.0, 1.0, 1.0));
    vec4 p_z = permute(a.z + p_y + vec4(0.0, 0.0, 1.0, 1.0));

    // 梯度向量计算（网页6的梯度点积法）
    vec3 g000 = normalize(vec3(p_z.x, p_z.y, p_z.z)) * 2.0 - 1.0;
    vec3 g001 = normalize(vec3(p_z.w, p_z.x, p_z.y)) * 2.0 - 1.0;
    vec3 g010 = normalize(vec3(p_z.y, p_z.z, p_z.w)) * 2.0 - 1.0;
    vec3 g011 = normalize(vec3(p_z.x, p_z.y, p_z.z)) * 2.0 - 1.0;
    vec3 g100 = normalize(vec3(p_z.z, p_z.w, p_z.x)) * 2.0 - 1.0;
    vec3 g101 = normalize(vec3(p_z.y, p_z.z, p_z.w)) * 2.0 - 1.0;
    vec3 g110 = normalize(vec3(p_z.w, p_z.x, p_z.y)) * 2.0 - 1.0;
    vec3 g111 = normalize(vec3(p_z.z, p_z.w, p_z.x)) * 2.0 - 1.0;

    // 点积计算（网页1的MOD3优化）
    float n000 = dot(g000, d);
    float n001 = dot(g001, d - vec3(1.0, 0.0, 0.0));
    float n010 = dot(g010, d - vec3(0.0, 1.0, 0.0));
    float n011 = dot(g011, d - vec3(1.0, 1.0, 0.0));
    float n100 = dot(g100, d - vec3(0.0, 0.0, 1.0));
    float n101 = dot(g101, d - vec3(1.0, 0.0, 1.0));
    float n110 = dot(g110, d - vec3(0.0, 1.0, 1.0));
    float n111 = dot(g111, d - vec3(1.0, 1.0, 1.0));

    // 三线性插值（网页6的双线性扩展）
    float nx00 = mix(n000, n001, u.x);
    float nx01 = mix(n010, n011, u.x);
    float nx10 = mix(n100, n101, u.x);
    float nx11 = mix(n110, n111, u.x);

    float nxy0 = mix(nx00, nx01, u.y);
    float nxy1 = mix(nx10, nx11, u.y);

    return mix(nxy0, nxy1, u.z) * 0.5 + 0.5; // 结果归一化到[0,1]
}

void main() {
    uint id = gl_GlobalInvocationID.x;
    if (id >= uint(particlesIn.length())) return;
    Particle p = particlesIn[id];

    vec3 pos = p.position.xyz;
    float noiseSeed = u_Time * float(id);

    vec3 turbulence = vec3(
        perlin_noise(pos + vec3(noiseSeed, 0., 0.)) * 2.0 - 1.0,
        perlin_noise(pos + vec3(0., noiseSeed, 0.)) * 2.0 - 1.0,
        perlin_noise(pos + vec3(0., 0., noiseSeed))
    ) * turbulenceForce * dt * 10.0;

    float t = mod(u_Time, noiseInterval);
    float strength = smoothstep(0.0, 0.2, t) * 
                    (1.0 - smoothstep(noiseDuration-0.2, noiseDuration, t));

    // 应用扰动方向（限制Y轴强度）
    turbulence.y = clamp(turbulence.y, 0.0, 1.0);
    p.speed.xyz += turbulence;
    particlesOut[id] = p;  // 写入输出缓冲
}

